steps.script:
var q = PhaseManager.get_current_phase_instance().get_battle_shock_queue()
var order = []
var hit = ""
for e in q:
	order.append(str(e.get("unit_id", "")) + ":" + str(e.get("reason", "")))
	if str(e.get("unit_id", "")) == "U_TANKBUSTAS_A":
		hit = "%s %d %s" % [str(e.get("reason", "")), int(e.get("battle_shock_bonus", 0)), str(e.get("battle_shock_malus_source", ""))]
print("[cus11e creeping dread] queue: ", order)
return hit

for i in range(5):
	var p = PhaseManager.get_current_phase_instance()
	if p == null or not p.has_pending_stratagem_window():
		break
	var w = p.get_pending_stratagem_window()
	NetworkIntegration.route_action({"type": "DECLINE_WINDOW_STRATAGEM", "player": int(w.get("player", 1)), "window_id": str(w.get("window_id", ""))})
return true

var t: String = tree.root.get_node("BattleShockSequenceDialog").find_child("TotalLabel", true, false).text
print("[cus11e creeping dread] total label: ", t)
return t.contains("(-1)")
